<?php

use App\Models\{AccountMapping, AccountingCurrency, BankAccount, ChartAccount, Company, CompanyMembership, FiscalPeriod, FiscalYear, Permission, PurchaseOrder, PurchaseOrderItem, Role, RoleAssignment, Supplier, SupplierBill, SupplierPayment, Tenant, TenantMembership, UnitOfMeasure, User, Product, ProductVariant};

function supplierBillFixture(): array
{
    $user = User::factory()->create(); $tenant = Tenant::factory()->create(); TenantMembership::create(['tenant_id'=>$tenant->id,'user_id'=>$user->id,'status'=>'active']);
    $permissions = collect(['procurement.manage','accounting.post'])->map(fn ($name) => Permission::firstOrCreate(['name'=>$name])); $role = Role::create(['tenant_id'=>$tenant->id,'name'=>'AP controller','slug'=>'ap-controller-'.fake()->unique()->numerify('####')]); $role->permissions()->sync($permissions->pluck('id')); RoleAssignment::create(['tenant_id'=>$tenant->id,'role_id'=>$role->id,'user_id'=>$user->id]);
    $company=Company::create(['tenant_id'=>$tenant->id,'name'=>'AP Company','code'=>'AP-CO','base_currency'=>'MMK']); CompanyMembership::create(['tenant_id'=>$tenant->id,'company_id'=>$company->id,'user_id'=>$user->id,'status'=>'active','joined_at'=>now()]); $supplier=Supplier::create(['tenant_id'=>$tenant->id,'name'=>'AP Supplier','code'=>'AP-SUP','status'=>'active']); $currency=AccountingCurrency::create(['tenant_id'=>$tenant->id,'code'=>'MMK','name'=>'Myanmar Kyat','decimal_places'=>0,'is_base'=>true]);
    $year=FiscalYear::create(['tenant_id'=>$tenant->id,'company_id'=>$company->id,'name'=>'FY 2026','starts_on'=>'2026-01-01','ends_on'=>'2026-12-31','state'=>'open']); $period=FiscalPeriod::create(['tenant_id'=>$tenant->id,'fiscal_year_id'=>$year->id,'name'=>'October 2026','starts_on'=>'2026-10-01','ends_on'=>'2026-10-31','state'=>'open']); $expense=ChartAccount::create(['tenant_id'=>$tenant->id,'company_id'=>$company->id,'code'=>'5100','name'=>'Purchases','type'=>'expense','normal_balance'=>'debit','is_active'=>true]); $ap=ChartAccount::create(['tenant_id'=>$tenant->id,'company_id'=>$company->id,'code'=>'2100','name'=>'Accounts Payable','type'=>'liability','normal_balance'=>'credit','is_control'=>true,'is_active'=>true]); $bank=ChartAccount::create(['tenant_id'=>$tenant->id,'company_id'=>$company->id,'code'=>'1100','name'=>'Bank','type'=>'asset','normal_balance'=>'debit','is_active'=>true]); AccountMapping::create(['tenant_id'=>$tenant->id,'company_id'=>$company->id,'mapping_key'=>'accounts_payable','account_id'=>$ap->id]); $bankAccount=BankAccount::create(['tenant_id'=>$tenant->id,'company_id'=>$company->id,'currency_id'=>$currency->id,'ledger_account_id'=>$bank->id,'name'=>'Operating bank','status'=>'active']);
    $unit=UnitOfMeasure::create(['tenant_id'=>$tenant->id,'name'=>'Each','code'=>'EA']); $product=Product::create(['tenant_id'=>$tenant->id,'name'=>'AP Item','slug'=>'ap-item','status'=>'active']); $variant=ProductVariant::create(['tenant_id'=>$tenant->id,'product_id'=>$product->id,'unit_id'=>$unit->id,'sku'=>'AP-1','internal_barcode'=>'AP-1','cost'=>'10','price'=>'10','is_active'=>true]); $order=PurchaseOrder::create(['tenant_id'=>$tenant->id,'company_id'=>$company->id,'supplier_id'=>$supplier->id,'created_by'=>$user->id,'number'=>'PO-AP-1','state'=>'approved','currency_id'=>$currency->id,'grand_total'=>'20','base_total'=>'20','order_date'=>'2026-10-29']); $item=PurchaseOrderItem::create(['tenant_id'=>$tenant->id,'purchase_order_id'=>$order->id,'variant_id'=>$variant->id,'ordered_quantity'=>'2','received_quantity'=>'0','returned_quantity'=>'0','unit_price'=>'10']);
    return compact('user','tenant','company','supplier','currency','period','expense','bankAccount','order','item');
}

it('creates, matches, approves, and posts a supplier bill without mixing customer payments', function (): void {
    $f=supplierBillFixture(); $headers=['X-Tenant-Id'=>$f['tenant']->id]; $payload=['company_id'=>$f['company']->id,'supplier_id'=>$f['supplier']->id,'purchase_order_id'=>$f['order']->id,'currency_id'=>$f['currency']->id,'currency_code'=>'MMK','supplier_reference'=>'SUP-INV-1','invoice_date'=>'2026-10-29','accounting_date'=>'2026-10-29','lines'=>[['purchase_order_item_id'=>$f['item']->id,'account_id'=>$f['expense']->id,'quantity'=>'2','unit_price'=>'10','discount_amount'=>'0','tax_amount'=>'0']]];
    $created=$this->actingAs($f['user'])->postJson('/api/v1/supplier-bills',$payload,$headers)->assertCreated()->assertJsonPath('data.state','draft'); $id=$created->json('data.id'); $this->actingAs($f['user'])->postJson('/api/v1/supplier-bills/'.$id.'/match',[], $headers)->assertOk()->assertJsonPath('data.matches.0.status','matched'); $this->actingAs($f['user'])->postJson('/api/v1/supplier-bills/'.$id.'/submit',[], $headers)->assertOk()->assertJsonPath('data.state','submitted'); $this->actingAs($f['user'])->postJson('/api/v1/supplier-bills/'.$id.'/approve',[], $headers)->assertOk()->assertJsonPath('data.state','approved'); $this->actingAs($f['user'])->postJson('/api/v1/supplier-bills/'.$id.'/post',[], $headers)->assertOk()->assertJsonPath('data.state','posted'); expect(SupplierBill::find($id)->accounting_entry_id)->not->toBeNull();
    $this->actingAs($f['user'])->postJson('/api/v1/supplier-bills',$payload,$headers)->assertUnprocessable();
});

it('posts supplier payments and rejects over-allocation', function (): void {
    $f=supplierBillFixture(); $headers=['X-Tenant-Id'=>$f['tenant']->id]; $bill=SupplierBill::create(['tenant_id'=>$f['tenant']->id,'company_id'=>$f['company']->id,'supplier_id'=>$f['supplier']->id,'currency_id'=>$f['currency']->id,'currency_code'=>'MMK','number'=>'BILL-PAY-1','supplier_reference'=>'INV-PAY-1','state'=>'posted','approval_status'=>'posted','invoice_date'=>'2026-10-29','accounting_date'=>'2026-10-29','grand_total'=>'100','total'=>'100']); $created=$this->actingAs($f['user'])->postJson('/api/v1/purchasing/payments',['company_id'=>$f['company']->id,'supplier_id'=>$f['supplier']->id,'bank_account_id'=>$f['bankAccount']->id,'currency_id'=>$f['currency']->id,'reference'=>'PAY-1','method'=>'bank_transfer','payment_date'=>'2026-10-29','amount'=>'60'],$headers)->assertCreated(); $paymentId=$created->json('data.id'); $this->actingAs($f['user'])->postJson('/api/v1/purchasing/payments/'.$paymentId.'/post',[],$headers)->assertOk()->assertJsonPath('data.state','posted'); $this->actingAs($f['user'])->postJson('/api/v1/purchasing/payments/'.$paymentId.'/allocate',['bill_id'=>$bill->id,'amount'=>'61'],$headers)->assertUnprocessable(); $this->actingAs($f['user'])->postJson('/api/v1/purchasing/payments/'.$paymentId.'/allocate',['bill_id'=>$bill->id,'amount'=>'60'],$headers)->assertCreated(); expect(SupplierPayment::find($paymentId)->state)->toBe('posted');
});
